contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address caller) public {
        address ownerBefore = c.owner();

        bool reverted = false;
        if (caller != ownerBefore) {
            // non-owner caller cannot reach transferOwnership from this test contract's direct call
            // so only test the owner path and zero address path, caller is implicitly address(this)
            // fall through: we only call as address(this), which is the owner from test's perspective
        }

        // The test contract is the owner (it deployed c), so it can call transferOwnership.
        // If newOwner is zero, it must revert; otherwise it must complete and set owner.
        if (newOwner == address(0)) {
            bool ok;
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
            assert(!ok);
        } else {
            c.transferOwnership(newOwner);
            assert(c.owner() == newOwner);
        }
    }

    receive() external payable {}
}

