contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount zero");
        require(address(this).balance >= amount, "insufficient test balance");

        uint256 supplyBefore = c.totalSupply();

        bool stakeReverted;
        try c.stake{value: 0}(amount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        uint256 supplyAfterStake = c.totalSupply();

        if (!stakeReverted) {
            assert(supplyAfterStake == supplyBefore + amount);
        }

        bool withdrawReverted;
        try c.withdraw(amount, false) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint256 supplyAfterWithdraw = c.totalSupply();

        if (!stakeReverted && !withdrawReverted) {
            assert(supplyAfterWithdraw == supplyBefore);
        } else if (!stakeReverted) {
            assert(supplyAfterWithdraw == supplyBefore + amount);
        } else {
            assert(supplyAfterWithdraw == supplyBefore);
        }
    }

    receive() external payable {}
}

