contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address _account, address _rewardsToken) public payable {
        require(_account != address(0));
        require(_rewardsToken != address(0));

        uint256 beforeEarned;
        bool beforeReverted;
        try c.earned(_account, _rewardsToken) returns (uint256 v) {
            beforeEarned = v;
            beforeReverted = false;
        } catch {
            beforeReverted = true;
        }

        uint256 paidBefore = c.userRewardPerTokenPaid(_account, _rewardsToken);
        uint256 claimBefore = c.claimableRewards(_account, _rewardsToken);
        uint256 balBefore = c.balanceOf(_account);

        uint256 afterEarned;
        bool afterReverted;
        try c.earned(_account, _rewardsToken) returns (uint256 v) {
            afterEarned = v;
            afterReverted = false;
        } catch {
            afterReverted = true;
        }

        uint256 paidAfter = c.userRewardPerTokenPaid(_account, _rewardsToken);
        uint256 claimAfter = c.claimableRewards(_account, _rewardsToken);
        uint256 balAfter = c.balanceOf(_account);

        assert(
            (beforeReverted == afterReverted) &&
            (beforeReverted || afterEarned == beforeEarned) &&
            (paidBefore == paidAfter) &&
            (claimBefore == claimAfter) &&
            (balBefore == balAfter)
        );
    }
}

