    }

    function run(uint256 amount) public {
        require(amount > 0, "amount must be positive");

        // Setup: ensure the caller has staking tokens and stake a positive amount.
        // The test contract must hold the staking token balance before staking.
        address staking = address(c.stakingToken());
        require(staking != address(0), "staking token not set");

        // Approve c to pull tokens from this test contract.
        IERC20(staking).approve(address(c), amount);

        // Stake exactly the requested amount.
        c.stake(amount);

        // Read state through the public surface.
        uint256 balThis = c.balanceOf(address(this));
        uint256 total = c.totalSupply();

        // Pick a reward token that exists; addReward is onlyOwner, and this test contract
        // is the deployer/owner of c, so it can initialize one reward token.
        address rewardToken = address(0xdead);
        c.addReward(rewardToken);

        // Read rewardPerToken for the reward token through the public view.
        uint256 rpt = c.rewardPerToken(rewardToken);
        uint40 finish = c.rewardPeriodFinish(rewardToken);

        // The core invariant: totalSupply must be at least this contract's balance,
        // and rewardPerToken must be non-negative (always true for uint) and must not revert.
        // More meaningfully: after staking, balanceOf(this) <= totalSupply, and
        // rewardPerToken(token) must equal rewardData[token].rewardPerTokenStored when
        // totalSupply() > 0 and no time/reward updates have occurred.
        assert(balThis <= total && rpt == 0 && finish >= block.timestamp);
    }

    receive() external payable {}
}

