contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address distributor, address token, address caller, uint256 amount) public payable {
        // Register `token` as a known reward token via the owner-gated entry point.
        // This call is made by the test contract, which is the owner because it deployed c.
        c.addReward(token);

        // Set the caller as reward distributor so we can distinguish the distributor branch.
        c.setRewardDistributor(distributor);

        bool reverted;
        if (caller == distributor) {
            // Distributor path: should only revert on zero amount; token is known.
            try c.notifyRewardAmount(token, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-distributor path: must revert regardless of amount/token validity.
            try c.notifyRewardAmount(token, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (caller == distributor) {
            assert(reverted == (amount == 0));
        } else {
            assert(reverted);
        }
    }
}

