    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(staker != address(0), "staker must be non-zero");

        uint256 beforeBalance = c.balanceOf(staker);
        require(beforeBalance >= amount, "staker must have enough balance");

        bool reverted;
        try c.migrateWithdraw(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.balanceOf(staker) == beforeBalance);
    }

    receive() external payable {}
}

