contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();
        bool callerIsOwner = (msg.sender == ownerBefore);
        bool validNewOwner = (newOwner != address(0));

        if (reverted) {
            assert(
                !callerIsOwner || !validNewOwner
            );
            assert(ownerAfter == ownerBefore);
        } else {
            assert(callerIsOwner && validNewOwner);
            assert(ownerAfter == newOwner);
        }
    }
}

