    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 beforeSupply = c.totalSupply();
        bool reverted;
        try c.totalSupply() returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterSupply = c.totalSupply();

        assert(
            (!reverted && beforeSupply == 0 && afterSupply == 0) ||
            (reverted && beforeSupply == afterSupply)
        );
    }

    receive() external payable {}
}

