contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address owner_, address token_) public {
        // State c already owns from its Ownable constructor: owner_ is the
        // current owner (unless owner_ == address(0) in which case the
        // constructor's implicit owner is address(0)).
        // The pre-existing reward data for token_ must be untouched before
        // the call: read the observable getters.
        bool knownBefore;
        (uint40 periodFinishBefore, , , ) = c.rewardData(token_);
        {
            uint256 lenBefore = 0;
            uint256 i = 0;
            while (true) {
                address t;
                try c.rewardTokens(i) returns (address tok) { t = tok; } catch { break; }
                lenBefore++;
                i++;
                if (i > 1e6) break;
                t;
            }
            knownBefore = _containsRewardTokens(lenBefore, token_);
        }

        bool reverted;
        try c.addReward(token_) { reverted = false; } catch { reverted = true; }

        bool knownAfter;
        {
            uint256 lenAfter = 0;
            uint256 i = 0;
            while (true) {
                address t;
                try c.rewardTokens(i) returns (address tok) { t = tok; } catch { break; }
                lenAfter++;
                i++;
                if (i > 1e6) break;
                t;
            }
            knownAfter = _containsRewardTokens(lenAfter, token_);
        }
        (uint40 periodFinishAfter, , uint40 lastUpdateTimeAfter, ) = c.rewardData(token_);

        bool ownerIsThis = address(this) == c.owner();
        bool shouldSucceed = ownerIsThis && !knownBefore;

        if (shouldSucceed) {
            // For a fresh token the reward data gets initialized to the
            // current timestamp and the token is appended to rewardTokens.
            assert(
                !reverted &&
                knownAfter &&
                lastUpdateTimeAfter == uint40(block.timestamp) &&
                periodFinishAfter == uint40(block.timestamp) &&
                !knownBefore
            );
        } else {
            // Any other caller/token must revert, and the reward data as
            // observable through the public getters and the rewardTokens array
            // must be unchanged by the attempted call.
            assert(
                reverted &&
                knownAfter == knownBefore &&
                periodFinishAfter == periodFinishBefore
            );
        }
    }

    function _containsRewardTokens(uint256 len, address token) private view returns (bool) {
        for (uint256 i = 0; i < len; i++) {
            if (c.rewardTokens(i) == token) return true;
        }
        return false;
    }

    receive() external payable {}
}

