            if (c.rewardTokens(i) == token_) { knownAfter = true; }
        }
        (uint40 periodFinishAfter, , uint40 lastUpdateTimeAfter, ) = c.rewardData(token_);

        bool expectedSuccess = ownerIsThis && (lastUpdateTimeBefore == 0);

        assert(
            (expectedSuccess && !reverted && knownAfter && lastUpdateTimeAfter == uint40(block.timestamp) && periodFinishAfter == uint40(block.timestamp)) ||
            (!expectedSuccess && reverted && knownAfter == knownBefore && periodFinishAfter == periodFinishBefore && lastUpdateTimeAfter == lastUpdateTimeBefore)
