contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _rewardToken, uint256 _amount) public payable {
        require(address(this).balance >= 0);
        // setup: add reward token as owner (test contract is owner)
        c.addReward(_rewardToken);
        // read the before value
        uint40 beforeFinish = c.rewardPeriodFinish(_rewardToken);
        // attempt to notify reward as distributor
        // test contract is not distributor, so this may revert
        bool reverted;
        try c.notifyRewardAmount(_rewardToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // read after
        uint40 afterFinish = c.rewardPeriodFinish(_rewardToken);

        // General rule: if notifyRewardAmount succeeds, periodFinish must be > block.timestamp
        // and also > beforeFinish (since it extends by DURATION)
        if (!reverted) {
            // afterFinish should be > block.timestamp (set to block.timestamp + DURATION)
            assert(afterFinish > block.timestamp);
            // also afterFinish should be >= beforeFinish (since it's extended)
            assert(afterFinish >= beforeFinish);
        } else {
            // if reverted, periodFinish should remain unchanged
            assert(afterFinish == beforeFinish);
        }
    }

    receive() external payable {}
}

