contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, address otherToken) public {
        require(token != address(0), "token zero");
        require(token != otherToken, "tokens equal");

        // C is Ownable and the deployer is the test contract, so onlyOwner calls succeed.
        c.addReward(token);

        uint256 total = c.totalSupply();
        uint256 stored = c.rewardPerToken(token);

        bool reverted;
        uint256 returned;
        try c.rewardPerToken(token) returns (uint256 r) {
            returned = r;
        } catch {
            reverted = true;
        }

        // The view call must not revert, and with no staked supply the reward index
        // must remain exactly at its stored value. Otherwise it can only grow,
        // since rewardPerTokenStored is non-negative and totalSupply divides a
        // non-negative accumulator added to it.
        assert(!reverted && (total == 0 ? returned == stored : returned >= stored));
    }

    receive() external payable {}
}

